service.method:

    	UPDATE SUSMT
      	   SET CHANGE_DATE        = ${current.DATE}
	         , CHANGE_TIME        = ${current.TIME}
	         , CHANGE_USER_ID     = ${session.ID}
	         , DEPT 			  = ${DEPT}
		     , POSITION           = ${POSITION}
		     , EMPLOYEE_NO        = ${EMPLOYEE_NO}
		     , USER_NAME_LOC      = ${USER_NAME_LOC}
		     , USER_NAME_ENG      = ${USER_NAME_ENG}
		     , MANAGER_POSITION   = ${MANAGER_POSITION}
		     , PROFILE_ATTACHE_NO = ${PROFILE}


			 , PASSWORD = ${NEW_PASSWORD}
			 , PW_RESET_FLAG = 'N'
			 , PW_RESET_DATE = ${current.DATE}  


      WHERE USER_ID  = ${session.ID}
        AND HOUSE_CODE = ${session.HOUSE_CODE}


	SELECT CODE_NO
	  FROM SADDR ADDR 
	 WHERE ADDR.CODE_NO = ${session.ID}
       AND ADDR.HOUSE_CODE = ${session.HOUSE_CODE}


	UPDATE SADDR 
       SET CHANGE_DATE 	   = ${current.DATE} 
	     , CHANGE_TIME     = ${current.TIME} 
	     , CHANGE_USER_ID  = ${session.ID} 
	     , EMAIL           = ${EMAIL} 
	     , PHONE_NO1       = ${PHONE_NO1} 
	     , PHONE_NO2       = ${PHONE_NO2} 
	     , FAX_NO          = ${FAX_NO} 
	     , ZIP_CODE        = ${ZIP_CODE} 
	     , ADDRESS_LOC     = ${ADDRESS_LOC} 
	     , ADDRESS_ENG     = ${ADDRESS_ENG} 
	     , DEL_FLAG        = 'N'
	 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
	       AND CODE_NO = ${session.ID}
